# A tiny numerical illustration -- NOT how real training works internally,
# but shows what 'the gradient points uphill' means in practice.
def error(w):
    return (w - 3) ** 2   # error is smallest (0) when w = 3

def approx_gradient(w, step=1e-4):
    return (error(w + step) - error(w - step)) / (2 * step)

for w in [0, 2, 3, 5]:
    print(f"w={w}: error={error(w):.2f}, gradient={approx_gradient(w):.2f}")

import torch
import torch.nn as nn

class TinyNet(nn.Module):
    def __init__(self):
        super().__init__()
        self.stack = nn.Sequential(
            nn.Linear(4, 8),
            nn.ReLU(),
            nn.Linear(8, 3),
        )
    def forward(self, x):
        return self.stack(x)

model = TinyNet()
x = torch.rand(1, 4)     # one example, 4 features
out = model(x)
print(out.shape)          # torch.Size([1, 3])

